import assert from "node:assert/strict";
import { report } from "../src/index.js";

test("report gives codes, sorted totals and the first code", () => {
  assert.deepEqual(report(["p,5", "q,3"]), { codes: ["p", "q"], totals: [3, 5], first: "p" });
});
